<script setup>
import { ref, computed } from 'vue'
import Icon from '../components/Icon.vue'
import ExpenseList from '../components/ExpenseList.vue'
import { store, openExpense } from '../store'
import { money, totals, consideredCents, today } from '../lib/domain'
const mode = ref('total'), selectedMonth = ref(today().slice(0, 7))
const sums = computed(() => totals(store.expenses))
const considered = computed(() => mode.value === 'total' ? sums.value.total : sums.value.paid)
const remaining = computed(() => store.budgetCents - considered.value)
const percent = computed(() => store.budgetCents > 0 ? considered.value / store.budgetCents * 100 : null)
const groups = computed(() => store.categories.map(c => ({ ...c, value: store.expenses.filter(e => e.categoryId === c.id).reduce((n, e) => n + consideredCents(e, mode.value), 0) })).sort((a, b) => b.value - a.value))
const recent = computed(() => [...store.expenses].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 5))
const monthBars = computed(() => {
  const end = selectedMonth.value || today().slice(0, 7)
  const [y, m] = end.split('-').map(Number)
  return Array.from({ length: 6 }, (_, i) => {
    const date = new Date(y, m - 6 + i, 1), key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`
    return { key, label: date.toLocaleDateString('pt-BR', { month: 'short' }).replace('.', ''), value: store.expenses.filter(e => e.date.startsWith(key)).reduce((n, e) => n + consideredCents(e, mode.value), 0) }
  })
})
const maxBar = computed(() => Math.max(...monthBars.value.map(b => b.value), 1))
const dateText = new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' })
</script>
<template>
  <div class="page-heading"><div><h1>Um olhar sobre a obra</h1><p class="muted">Tudo organizado para você construir com tranquilidade.</p></div><button class="button" @click="openExpense()"><Icon name="plus" :size="18"/>Adicionar despesa</button></div>
  <div class="overview-toolbar"><div class="segmented" aria-label="Visão dos gastos"><button :class="{ selected: mode === 'total' }" :aria-pressed="mode === 'total'" @click="mode = 'total'">Valor gasto total</button><button :class="{ selected: mode === 'partial' }" :aria-pressed="mode === 'partial'" @click="mode = 'partial'">Valor gasto parcial</button></div><span class="muted small date-stamp">{{ dateText }}</span></div><p class="view-explanation">{{ mode === 'total' ? 'Inclui o valor integral das compras, mesmo com parcelas futuras.' : 'Inclui PIX/Débito e somente as parcelas de crédito informadas como pagas.' }} Valores acumulados de toda a reforma.</p>
  <section class="stats-grid" aria-label="Indicadores da reforma"><article class="stat-card"><div class="stat-top"><span>Expectativa de gasto</span><span class="stat-icon"><Icon name="wallet"/></span></div><strong class="stat-value">{{ money(store.budgetCents) }}</strong><RouterLink to="/configuracoes" class="stat-foot">Ajustar orçamento <Icon name="up" :size="14"/></RouterLink></article><article class="stat-card"><div class="stat-top"><span>{{ mode === 'total' ? 'Gasto total' : 'Gasto parcial' }}</span><span class="stat-icon"><Icon name="expenses"/></span></div><strong class="stat-value">{{ money(considered) }}</strong><span class="stat-foot muted">{{ store.expenses.length }} {{ store.expenses.length === 1 ? 'despesa registrada' : 'despesas registradas' }}</span></article><article :class="['stat-card', 'accent-card', { exceeded: remaining < 0 }]"><div class="stat-top"><span>{{ remaining < 0 ? 'Orçamento excedido' : 'Saldo do orçamento' }}</span><span class="stat-icon"><Icon name="up"/></span></div><strong class="stat-value">{{ money(Math.abs(remaining)) }}</strong><span class="stat-foot">{{ mode === 'total' ? 'Após todas as compras registradas' : 'Após os pagamentos informados' }}</span></article><article class="stat-card"><div class="stat-top"><span>Ainda a pagar no crédito</span><span class="stat-icon"><Icon name="credit"/></span></div><strong class="stat-value">{{ money(sums.outstanding) }}</strong><span class="stat-foot muted">Parcelas que ainda não foram quitadas</span></article></section>
  <section class="panel budget-panel"><div class="budget-heading"><div class="inline"><span class="soft-icon"><Icon name="house"/></span><div><h2>Seu orçamento, de perto</h2><p class="muted small">{{ mode === 'total' ? 'Compras registradas' : 'Pagamentos informados' }} em relação ao planejado</p></div></div><strong class="budget-percent" :class="{ 'danger-text': percent > 100 }">{{ percent === null ? 'Sem orçamento' : `${percent.toLocaleString('pt-BR', { maximumFractionDigits: 1 })}%` }}</strong></div><div class="progress-track" role="progressbar" aria-label="Orçamento utilizado" :aria-valuenow="percent === null ? 0 : Math.round(Math.min(percent, 100))" aria-valuemin="0" aria-valuemax="100" :aria-valuetext="percent === null ? 'Orçamento não definido' : `${percent.toFixed(1)}% utilizado`"><span :class="{ over: percent > 100 }" :style="{ width: `${Math.min(percent || 0, 100)}%` }"/></div><div class="between small muted"><span>{{ money(considered) }} utilizados</span><span>Meta: {{ money(store.budgetCents) }}</span></div><p v-if="!store.budgetCents" class="hint">Defina uma expectativa de gasto em Configurações para acompanhar o percentual.</p></section>
  <div class="charts-grid"><section class="panel"><div class="panel-heading"><div><h2>Onde estamos investindo</h2><p class="small muted">Gastos por categoria · {{ mode === 'total' ? 'total' : 'parcial' }}</p></div><span class="subtle-chip">Toda a reforma</span></div><div v-if="considered" class="category-chart"><div class="category-stack" aria-hidden="true"><span v-for="g in groups.filter(g => g.value)" :key="g.id" :style="{ width: `${g.value / considered * 100}%`, background: g.color }"/></div><div v-for="g in groups" :key="g.id" class="category-row"><span class="legend-dot" :style="{ background: g.color }"/><span>{{ g.name }}</span><strong>{{ money(g.value) }}</strong><span class="muted category-percent">{{ (g.value / considered * 100).toFixed(0) }}%</span></div></div><div v-else class="empty small">Os gastos desta visão aparecerão aqui.</div></section>
  <section class="panel"><div class="panel-heading"><div><h2>Compras por mês</h2><p class="small muted">Seis meses até o mês selecionado</p></div><label class="sr-only" for="chart-month">Último mês do gráfico</label><input id="chart-month" v-model="selectedMonth" type="month" min="1900-06" max="2199-12" class="month-input"/></div><div class="bar-chart"><div v-for="bar in monthBars" :key="bar.key" class="bar-column"><span class="bar-value">{{ money(bar.value) }}</span><div class="bar-well"><div :class="['bar', { latest: bar.key === selectedMonth }]" :style="{ height: `${bar.value ? Math.max(bar.value / maxBar * 100, 3) : 0}%` }" :title="`${bar.key}: ${money(bar.value)}`"/></div><span class="bar-label">{{ bar.label }}</span></div></div><p class="chart-note">{{ mode === 'partial' ? 'Valor já pago, agrupado pela data da compra. Não representa o mês real do pagamento das parcelas.' : 'Compras agrupadas pela data do lançamento, incluindo parcelas futuras.' }}</p></section></div>
  <section class="panel recent-panel"><div class="panel-heading"><div><h2>Últimos registros</h2><p class="small muted">Os gastos mais recentes da sua reforma</p></div><RouterLink to="/despesas" class="text-button inline">Ver todas<Icon name="arrow" :size="16"/></RouterLink></div><ExpenseList :expenses="recent" compact/></section>
</template>
